def run(*args):
    subprocess.run(args,check=True)
def read(path):
    return Path(path).read_text()
def write(path,data):
    Path(path).write_text(data)
def repl(path,old,new,count=1):
    data=read(path)
    if old not in data:
        raise SystemExit(f'missing expected text in {path}: {old[:160]!r}')
    write(path,data.replace(old,new,count))
def regex_repl(path,pattern,replacement,count=1,flags=0):
    data=read(path)
    data2,n=re.subn(pattern,replacement,data,count=count,flags=flags)
    if n!=count:
        raise SystemExit(f'expected {count} regex replacement(s) in {path}, got {n}: {pattern}')
    write(path,data2)

